WITH filtered AS (SELECT id, product_name, category, brand, price, tags, supplier_id, CONCAT(product_name, ' ', category) AS product_name_category, SIZE(tags) AS tags_count, COALESCE(brand, 'UNKNOWN') AS brand_filled FROM products WHERE price <= 580) SELECT brand, CASE WHEN tags_count >= 73 THEN 'LARGE' ELSE 'SMALL' END AS tags_count_tier, SIZE(COLLECT_SET(category)) AS num_categories, ROUND(AVG(price), 2) AS avg_price FROM filtered GROUP BY brand, CASE WHEN tags_count >= 73 THEN 'LARGE' ELSE 'SMALL' END HAVING avg_price < 1000000 ORDER BY avg_price
